create table if not exists public.customers(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,full_name text not null,phone text,email text,created_at timestamptz not null default now());
create table if not exists public.inventory_parts(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,sku text not null,name text not null,category text not null,stock integer not null default 0,reserved integer not null default 0,reorder_level integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.invoices(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,repair_job_id uuid references public.repair_jobs(id) on delete set null,total numeric(10,2) not null default 0,paid numeric(10,2) not null default 0,status text not null default 'Draft',created_at timestamptz not null default now());
create table if not exists public.appointments(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,customer_id uuid references public.customers(id) on delete set null,scheduled_at timestamptz not null,service text not null,mode text not null,status text not null default 'Scheduled');
create table if not exists public.quality_checks(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,repair_job_id uuid not null references public.repair_jobs(id) on delete cascade,checks jsonb not null default '{}'::jsonb,passed boolean not null default false,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['customers','inventory_parts','invoices','appointments','quality_checks'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id)',t||'_own_all',t);end loop;end $$;
